solution:
pub type Either[L, R] = enum {
  Left(value: L),
  Right(value: R),
}

fn is_right[L, R](e: &Either[L, R]) -> Bool {
  match e {
    Either::Right(_) => true,
    Either::Left(_) => false,
  }
}

fn unwrap_right[L, R](e: Either[L, R]) -> R
  requires: is_right(&e);
{
  match e {
    Either::Right(v) => v,
    Either::Left(_) => panic("unwrap_right on Left"),
  }
}

fn main() -> Int {
  let e: Either[Str, Int] = Either::Right(42);
  return unwrap_right(e);
}
